        CountDownLatch done = new CountDownLatch(1);
        AtomicInteger exitCode = new AtomicInteger(0);
        String inputPath = parseInputPath(args, exitCode);

        if (inputPath == null) {
            System.err.println("Error: missing --input=<file> argument");
