        HeadlessApplicationConfiguration configuration = new HeadlessApplicationConfiguration();
        new HeadlessApplication(new LocalizationConsole(inputPath, done, exitCode), configuration);

        done.await();
        System.out.flush();
        System.err.flush();
        System.exit(exitCode.get());
