        if (args.length != 1 || !args[0].startsWith("--input=")) {
            exitCode.set(1);
            return null;
        }

        String inputPath = args[0].substring("--input=".length());
        if (inputPath.isEmpty()) {
            exitCode.set(1);
            return null;
        }

        return inputPath;
