        public void create() {
            try {
                processCommands();
                exitCode.set(0);
            } catch (CommandException error) {
                exitCode.set(1);
                System.err.println(error.getMessage());
            } catch (IOException error) {
                exitCode.set(1);
                System.err.println("Error: " + error.getMessage());
            } finally {
                System.out.flush();
                System.err.flush();
                done.countDown();
                Gdx.app.exit();
            }
        }

